import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int total = 0;
        for (int i = 1; i <= n; i++) {
            total = total + i;
        }

        System.out.println("一共 " + total + " 条{noun}喵");
    }
}
